input_schema:
{
  "type": "object",
  "properties": {
    "topic": {
      "type": "string",
      "description": "用户提供的研究课题"
    },
    "crossrefQueries": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "maxItems": 3,
      "description": "由 AI 从课题生成的英文检索词组：技术与业务、业务与系统类型、技术与系统类型"
    },
    "cnkiKeywords": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "maxItems": 6,
      "description": "AI 根据课题生成的 1–6 组中文检索词，覆盖核心技术、学业指导/发展/支持等领域表达及系统类型"
    }
  },
  "required": [
    "topic",
    "crossrefQueries",
    "cnkiKeywords"
  ]
}
